    // Create method registry object for this class
    JSValue methods = JS_NewObject(ctx);

    JS_SetPropertyStr(ctx, methods, "get_device_count",
        JS_NewCFunction(ctx, js_UPNP_get_device_count, "get_device_count", 1));
    JS_SetPropertyStr(ctx, methods, "get_device",
        JS_NewCFunction(ctx, js_UPNP_get_device, "get_device", 2));
    JS_SetPropertyStr(ctx, methods, "add_device",
        JS_NewCFunction(ctx, js_UPNP_add_device, "add_device", 2));
    JS_SetPropertyStr(ctx, methods, "set_device",
        JS_NewCFunction(ctx, js_UPNP_set_device, "set_device", 3));
    JS_SetPropertyStr(ctx, methods, "remove_device",
        JS_NewCFunction(ctx, js_UPNP_remove_device, "remove_device", 2));
    JS_SetPropertyStr(ctx, methods, "clear_devices",
        JS_NewCFunction(ctx, js_UPNP_clear_devices, "clear_devices", 1));
    JS_SetPropertyStr(ctx, methods, "get_gateway",
        JS_NewCFunction(ctx, js_UPNP_get_gateway, "get_gateway", 1));
    JS_SetPropertyStr(ctx, methods, "discover",
        JS_NewCFunction(ctx, js_UPNP_discover, "discover", 4));
    JS_SetPropertyStr(ctx, methods, "query_external_address",
        JS_NewCFunction(ctx, js_UPNP_query_external_address, "query_external_address", 1));
    JS_SetPropertyStr(ctx, methods, "add_port_mapping",
        JS_NewCFunction(ctx, js_UPNP_add_port_mapping, "add_port_mapping", 6));
    JS_SetPropertyStr(ctx, methods, "delete_port_mapping",
        JS_NewCFunction(ctx, js_UPNP_delete_port_mapping, "delete_port_mapping", 3));

    // Create property getters/setters registry
    JSValue props = JS_NewObject(ctx);

    {
        JSValue prop_obj = JS_NewObject(ctx);
        JS_SetPropertyStr(ctx, prop_obj, "get",
            JS_NewCFunction(ctx, js_UPNP_get_discover_multicast_if, "get_discover_multicast_if", 1));
        JS_SetPropertyStr(ctx, prop_obj, "set",
            JS_NewCFunction(ctx, js_UPNP_set_discover_multicast_if, "set_discover_multicast_if", 2));
        JS_SetPropertyStr(ctx, props, "discover_multicast_if", prop_obj);
    }
    {
        JSValue prop_obj = JS_NewObject(ctx);
        JS_SetPropertyStr(ctx, prop_obj, "get",
            JS_NewCFunction(ctx, js_UPNP_get_discover_local_port, "get_discover_local_port", 1));
        JS_SetPropertyStr(ctx, prop_obj, "set",
            JS_NewCFunction(ctx, js_UPNP_set_discover_local_port, "set_discover_local_port", 2));
        JS_SetPropertyStr(ctx, props, "discover_local_port", prop_obj);
    }
    {
        JSValue prop_obj = JS_NewObject(ctx);
        JS_SetPropertyStr(ctx, prop_obj, "get",
            JS_NewCFunction(ctx, js_UPNP_get_discover_ipv6, "get_discover_ipv6", 1));
        JS_SetPropertyStr(ctx, prop_obj, "set",
            JS_NewCFunction(ctx, js_UPNP_set_discover_ipv6, "set_discover_ipv6", 2));
        JS_SetPropertyStr(ctx, props, "discover_ipv6", prop_obj);
    }

    // Register signals array
    JSValue signals_arr = JS_NewArray(ctx);

    // Register class info
    JSValue class_info = JS_NewObject(ctx);
    JS_SetPropertyStr(ctx, class_info, "methods", methods);
    JS_SetPropertyStr(ctx, class_info, "properties", props);
    JS_SetPropertyStr(ctx, class_info, "signals", signals_arr);
